  { n:3, title:"Die Bibliothek", place:"Universität, Bibliothek.", place_ku:"زانکۆ، پەرتووکخانە.", lines:[
    {t:"d", who:"[N]", s:"Die Bibliothek ist riesig. So viele Bücher!"},
    {t:"d", who:"Anna", s:"Hier findest du alles, was du für dein Studium brauchst."},
    {t:"d", who:"[N]", s:"Ich brauche ein Buch über Statik. Weißt du, wo das ist?"},
    {t:"d", who:"Anna", s:"Das ist in Gang 5, rechts. Komm, ich zeige es dir."},
    {t:"d", who:"[N]", s:"Kann ich die Bücher ausleihen?"},
    {t:"d", who:"Anna", s:"Ja, du brauchst nur deinen Studentenausweis."}
  ]},
  { n:4, title:"Die Lerngruppe", place:"Universität, Gruppenraum.", place_ku:"زانکۆ، ژووری گروپ.", lines:[
    {t:"d", who:"Lukas", s:"Ich habe eine Idee. Wir gründen eine Lerngruppe. Das hilft uns allen."},
    {t:"d", who:"[N]", s:"Das ist eine gute Idee. Ich lerne besser mit anderen."},
    {t:"d", who:"Anna", s:"Ich bin auch dabei. Wir können uns jeden Mittwoch um 16 Uhr treffen."},
    {t:"d", who:"Lukas", s:"Perfekt. Dann können wir Aufgaben besprechen und uns auf Klausuren vorbereiten."},
    {t:"d", who:"[N]", s:"Das wird mir sehr helfen. Die Fachbegriffe sind schwer."},
    {t:"d", who:"Lukas", s:"Keine Sorge. Du wirst sie schnell lernen."}
  ]},
  { n:5, title:"Die Aufgaben", place:"Universität, Gruppenraum. Eine Woche später.", place_ku:"زانکۆ، ژووری گروپ. یەک هەفتە دواتر.", lines:[
    {t:"d", who:"Lukas", s:"Wir haben eine Aufgabe von Professor Müller. Ein Projekt über Brückenbau."},
    {t:"d", who:"[N]", s:"Brückenbau? Das ist mein Fach! In meinem Heimatland habe ich an einem Brückenprojekt gearbeitet."},
    {t:"d", who:"Anna", s:"Wirklich? Das ist perfekt. Dann kannst du uns helfen."},
    {t:"d", who:"Lukas", s:"Ja, wir brauchen jemanden mit Erfahrung."},
    {t:"d", who:"[N]", s:"Natürlich helfe ich. Ich erstelle einen Zeitplan und teile die Aufgaben auf."}
  ]},
  { n:6, title:"Nach der Uni", place:"Universität, Ausgang.", place_ku:"زانکۆ، دەروازە.", lines:[
    {t:"d", who:"[N]", s:"Das war ein guter Tag. Die Vorlesung war interessant, und ich habe neue Freunde gefunden."},
    {t:"d", who:"Anna", s:"Ja, Lukas ist sehr nett. Und er ist wirklich gut in seinem Fach."},
    {t:"d", who:"[N]", s:"Ich bin froh, dass ich mich für das Studium entschieden habe."},
    {t:"d", who:"Anna", s:"Das ist der richtige Weg, [N]."},
    {t:"d", who:"[N]", s:"Danke, Anna. Für alles."},
    {t:"d", who:"Anna", s:"Kein Problem. Wir gehen jetzt noch einen Kaffee trinken?"},
    {t:"d", who:"[N]", s:"Gerne."}
  ]}
